R.append((7813247,
("Pez espada asado con salsa sobre lentejas puy", "Un pescado firme y delicioso servido con lentejas sustanciosas: un platillo ligero pero nutritivo.", "4", "338 g",
 ["250 g de lentejas puy", "2 dientes de ajo, machacados", "600 ml de caldo de verduras", "4 tomates, picados en trozos grandes", "1 manojo de cebollines, picados", "4 trozos de 125 g de pez espada", "1 cucharada de aceite", "pimienta negra, para sazonar", "6 cucharadas de hierbas frescas mixtas (por ejemplo, perejil, cilantro, menta)", "2 cucharadas de alcaparras, escurridas", "4 filetes de anchoa", "ralladura y jugo de 1 limón", "2 cucharadas de aceite de oliva"],
 ["Precaliente el horno a 220 °C (gas 7).", "Ponga las lentejas en una olla mediana con el ajo y el caldo, deje que hierva y cocine a fuego lento de 15 a 20 minutos, hasta que estén tiernas. Escurra el exceso de líquido y luego agregue los tomates y los cebollines y mezcle bien para integrar. Sazone.", "Mientras tanto, coloque el pez espada en una charola para hornear, rocíe con el aceite y sazone. Hornee unos 10 minutos, hasta que esté crujiente y bien cocido por dentro.", "Para preparar la salsa, ponga todos los ingredientes de la salsa en una licuadora o procesador de alimentos y procese hasta integrar, pero conservando algo de textura.", "Para servir, reparta las lentejas en platos, coloque encima un trozo de pez espada y luego vierta la salsa con una cuchara."],
 ["Los niños, las mujeres embarazadas y las mujeres que intentan quedar embarazadas no deben comer pez espada, ya que contiene más mercurio que otros pescados. A los demás adultos se les aconseja no comer más de una porción de pez espada por semana.", "@FV"], []),
("سمك أبو سيف المشوي مع الصلصة على عدس بوي", "سمك متماسك لذيذ يُقدَّم مع عدس مشبع، طبق خفيف لكنه مغذٍّ.", "4", "338 جم",
 ["250 جم عدس بوي", "2 فص ثوم، مهروسة", "600 مل مرق خضار", "4 حبات طماطم، مفرومة فرمًا خشنًا", "1 حزمة بصل أخضر، مفرومة", "4 قطع بوزن 125 جم من سمك أبو سيف", "1 ملعقة كبيرة زيت", "فلفل أسود، للتتبيل", "6 ملاعق كبيرة أعشاب طازجة مشكلة (مثل البقدونس والكزبرة الخضراء والنعناع)", "2 ملعقة كبيرة كبر، مصفى", "4 شرائح أنشوجة", "قشر مبشور وعصير ليمونة واحدة", "2 ملعقة كبيرة زيت زيتون"],
 ["سخّن الفرن مسبقًا إلى 220° مئوية (درجة الغاز 7).", "ضع العدس في قدر متوسط مع الثوم والمرق، واتركه حتى يغلي ثم دعه على نار هادئة لمدة 15–20 دقيقة حتى يلين. صفِّ أي سائل زائد ثم أضف الطماطم والبصل الأخضر وقلّب جيدًا لدمجها. تبّل.", "وفي هذه الأثناء، ضع سمك أبو سيف على صينية خبز، ورش عليه الزيت وتبّله. ضعه في الفرن واطهه لمدة 10 دقائق تقريبًا حتى يصبح مقرمشًا وناضجًا تمامًا.", "لتحضير الصلصة، ضع جميع مكونات الصلصة في خلاط أو محضّرة طعام واخلطها حتى تتجانس مع الإبقاء على بعض القوام.", "للتقديم، اسكب العدس بالملعقة في أطباق التقديم، وضع فوقه قطعة من سمك أبو سيف، ثم اسكب الصلصة فوقه."],
 ["لا ينبغي للأطفال والحوامل والنساء اللاتي يحاولن الحمل تناول سمك أبو سيف لأنه يحتوي على نسبة زئبق أعلى من الأسماك الأخرى. ويُنصح البالغون الآخرون بعدم تناول أكثر من حصة واحدة من سمك أبو سيف في الأسبوع.", "@FV"], [])))
build(4, R)
